import os
import base64
import requests

def extract_text(payload, config=None):
    config = config or {}
    endpoint = config.get("endpoint") or os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    api_key = config.get("api_key") or os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_API_KEY")
    api_version = config.get("api_version", "2024-07-31-preview")
    model_id = config.get("model_id", "prebuilt-read")
    if not endpoint or not api_key:
        raise ValueError("Missing Azure Document Intelligence credentials")
    if isinstance(payload, (bytes, bytearray)):
        body = {"base64Source": base64.b64encode(payload).decode("utf-8")}
    elif isinstance(payload, str):
        if payload.startswith(("http://", "https://")):
            body = {"urlSource": payload}
        elif os.path.isfile(payload):
            with open(payload, "rb") as f:
                body = {"base64Source": base64.b64encode(f.read()).decode("utf-8")}
        else:
            raise ValueError("String payload must be a file path or URL")
    else:
        raise TypeError("payload must be bytes, bytearray, file path, or URL")

    analyze_url = f"{endpoint.rstrip('/')}/documentintelligence/documentModels/{model_id}:analyze?api-version={api_version}"
    headers = {
        "Ocp-Apim-Subscription-Key": api_key,
        "Content-Type": "application/json",
    }
    resp = requests.post(analyze_url, headers=headers, json=body, timeout=60)
    resp.raise_for_status()
    operation_url = resp.headers.get("operation-location")
    if not operation_url:
        raise RuntimeError("Azure Document Intelligence did not return operation-location")

    while True:
        poll = requests.get(operation_url, headers={"Ocp-Apim-Subscription-Key": api_key}, timeout=60)
        poll.raise_for_status()
        data = poll.json()
        status = data.get("status")
        if status == "succeeded":
            analyze_result = data.get("analyzeResult", {})
            result = analyze_result.get("content")
            if result is None:
                pages = analyze_result.get("pages", [])
                lines = []
                for page in pages:
                    for line in page.get("lines", []):
                        content = line.get("content")
                        if content:
                            lines.append(content)
                result = "\n".join(lines)
            break
        if status in {"failed", "canceled"}:
            raise RuntimeError(f"Azure Document Intelligence OCR failed with status: {status}")
    return result
